statement-execution-processor.statement:
declare
    v_owner_name VARCHAR2(4000) := {#0};
    v_object_name VARCHAR2(4000) := {#1};
    v_java_name VARCHAR2(4000) := v_owner_name || '.' || v_object_name;
    v_lob_table VARCHAR2(4000) := v_owner_name || '."CREATE$JAVA$LOB$TABLE"';
    v_content BLOB := {#2};
    v_content_id VARCHAR2(128) := SYS_GUID();
begin
    insert into {0}."CREATE$JAVA$LOB$TABLE" ("NAME", "LOB", "LOADTIME") VALUES (v_content_id, v_content, SYSDATE);

    if v_content is null then
        execute immediate 'create or replace java resource named ' || v_java_name || ' using blob (select EMPTY_BLOB() from DUAL)';
    else
        execute immediate 'create or replace java resource named ' || v_java_name || ' using blob "LOB" from ' || v_lob_table || ' where "NAME" = ''' || v_content_id || '''';
    end if;
    delete {0}."CREATE$JAVA$LOB$TABLE" where "NAME" = v_content_id;
exception
    when others then
        delete {0}."CREATE$JAVA$LOB$TABLE" where "NAME" = v_content_id;
    raise;
end;

declare
    v_owner_name VARCHAR2(4000) := {#0};
    v_lob_table VARCHAR2(4000) := v_owner_name || '."CREATE$JAVA$LOB$TABLE"';
